/** Resolve a wall-clock time, using the earlier occurrence for a fold and
 * moving forward by the size of a gap for nonexistent times. */
function localInstants(wall: Date, timeZone: string): number[] {
  const target = wall.getTime();
  const offsets = new Set<number>();
  for (const delta of [-2, -1, 0, 1, 2]) {
    const sample = target + delta * DAY_MS;
    offsets.add(localFields(new Date(sample), timeZone).getTime() - sample);
  }
  const candidates = [...offsets].map((offset) => target - offset);
