  return [candidates.filter((candidate) => localFields(new Date(candidate), timeZone).getTime() > target)
    .sort((a, b) => localFields(new Date(a), timeZone).getTime() - localFields(new Date(b), timeZone).getTime())[0]];
}

/** Midnight on the local calendar date, optionally shifted by calendar days. */
export function localDayStart(reference: Date, timeZone: string, days = 0): IsoTimestamp {
  const wall = localFields(reference, timeZone);
  wall.setUTCHours(0, 0, 0, 0);
  wall.setUTCDate(wall.getUTCDate() + days);
  return toIsoTimestamp(new Date(localInstants(wall, timeZone)[0]));
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return localDayStart(reference, timeZone);
}

/** A due date becomes overdue only after its local calendar day ends. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = \"UTC\",
): boolean {
  if (dueAt === null) return false;
