import { afterAll, beforeAll, describe, expect, it, vi } from \"vitest\";
import { organizationSettingsSchema } from \"@/schemas/organization\";
import { runCleanupArchivedJob } from \"@/server/jobs/cleanup-archived-job\";
import * as activityRepo from \"@/server/repositories/activity-repository\";
import * as orgRepo from \"@/server/repositories/organization-repository\";
import * as usageRepo from \"@/server/repositories/usage-repository\";
import { updateOrganization } from \"@/server/services/organization-service\";
import { getPlanLimits } from \"@/config/plan-limits\";
import { createTenant, useTemporaryDatabase } from \"../server/_support/fixtures\";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => { cleanup(); });

describe(\"workspace clock\", () => {
  it(\"defaults, persists, validates, and atomically rejects invalid zones\", async () => {
    const tenant = await createTenant(\"clock-settings\");
    expect(tenant.org.settings.timeZone).toBe(\"UTC\");
    expect(organizationSettingsSchema.parse({}).timeZone).toBe(\"UTC\");
    expect(organizationSettingsSchema.safeParse({ timeZone: \"Invalid/Zone\" }).success).toBe(false);
    await updateOrganization(tenant.actors.owner, { orgId: tenant.org.id, settings: { timeZone: \"Asia/Tokyo\" } });
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe(\"Asia/Tokyo\");
    await expect(updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id, name: \"Should not change\", settings: { timeZone: \"Invalid/Zone\" },
    })).rejects.toThrow(RangeError);
    const org = await orgRepo.findOrgById(tenant.org.id);
    expect(org?.name).toBe(tenant.org.name);
    expect(org?.settings.timeZone).toBe(\"Asia/Tokyo\");
  });

  it(\"cuts retention at local midnight on the earlier calendar date\", async () => {
    const tenant = await createTenant(\"clock-retention\", \"free\");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone: \"America/New_York\" } });
    await usageRepo.recomputeUsage(tenant.org.id);
    const spy = vi.spyOn(activityRepo, \"purgeActivityBefore\");
    try {
      const now = new Date(\"2026-04-08T16:00:00Z\");
      const date = new Date(\"2026-04-08T00:00:00Z\");
      date.setUTCDate(date.getUTCDate() - getPlanLimits(\"free\").retentionDays);
      // The free plan's cutoff date is before the spring transition, in EST.
      date.setUTCHours(5);
      await runCleanupArchivedJob(now);
      expect(spy).toHaveBeenCalledWith(tenant.org.id, date.toISOString());
    } finally { spy.mockRestore(); }
  });
});
